@push('scripts')
<script>
(function(){var tree=document.getElementById('recipient-tree');if(!tree)return;var people=function(){return Array.prototype.slice.call(tree.querySelectorAll('.recipient-person-checkbox'));};function sync(group){var parent=group.querySelector('.recipient-department-checkbox'),children=Array.prototype.slice.call(group.querySelectorAll('.recipient-person-checkbox')),checked=children.filter(function(item){return item.checked;}).length;parent.checked=checked===children.length&&children.length>0;parent.indeterminate=checked>0&&checked<children.length;}function update(){Array.prototype.forEach.call(tree.querySelectorAll('.recipient-department'),sync);document.getElementById('recipient-selected-count').textContent='已选 '+people().filter(function(item){return item.checked;}).length+' 人 · ';}tree.addEventListener('change',function(event){if(event.target.classList.contains('recipient-department-checkbox'))Array.prototype.forEach.call(event.target.closest('.recipient-department').querySelectorAll('.recipient-person-checkbox'),function(item){item.checked=event.target.checked;});update();});document.getElementById('select-all-recipients').onclick=function(){people().forEach(function(item){item.checked=true;});update();};document.getElementById('clear-recipients').onclick=function(){people().forEach(function(item){item.checked=false;});update();};update();})();
(function(){var zone=document.getElementById('message-upload-zone'),input=document.getElementById('message-image-input'),preview=document.getElementById('message-image-preview'),pasteButton=document.getElementById('message-paste-btn'),error=document.getElementById('message-upload-error');if(!zone||!input)return;var files=[];function showError(message){error.textContent=message||'';error.style.display=message?'block':'none';}function fileKey(file){return [file.name,file.size,file.lastModified].join('|');}function syncInput(){try{var transfer=new DataTransfer();files.forEach(function(file){transfer.items.add(file);});input.files=transfer.files;}catch(e){showError('当前浏览器不支持粘贴文件，请点击选择图片。');}}function render(){preview.innerHTML='';files.forEach(function(file,index){var item=document.createElement('div');item.className='message-preview-item';var image=document.createElement('img');image.src=URL.createObjectURL(file);image.alt=file.name;var remove=document.createElement('button');remove.type='button';remove.className='message-preview-remove';remove.innerHTML='&times;';remove.title='删除图片';remove.onclick=function(event){event.stopPropagation();files.splice(index,1);syncInput();render();};item.appendChild(image);item.appendChild(remove);preview.appendChild(item);});}function addFiles(incoming){showError('');Array.prototype.forEach.call(incoming||[],function(file){if(['image/jpeg','image/png','image/webp'].indexOf(file.type)<0){showError('仅支持 JPG、PNG、WEBP 图片。');return;}if(file.size>5*1024*1024){showError('图片 '+file.name+' 超过 5MB。');return;}if(files.some(function(existing){return fileKey(existing)===fileKey(file);}))return;if(files.length>=6){showError('每条消息最多上传 6 张图片。');return;}files.push(file);});syncInput();render();}function waitForKeyboardPaste(){zone.classList.add('is-paste-target');zone.focus();showError('浏览器未允许直接读取剪贴板，请在此处按 Ctrl+V 粘贴图片。');}zone.addEventListener('click',function(event){if(event.target.closest('.message-paste-btn')||event.target.closest('.message-preview-remove'))return;input.click();});input.addEventListener('change',function(){addFiles(Array.prototype.slice.call(input.files||[]));});pasteButton.addEventListener('click',async function(event){event.preventDefault();event.stopPropagation();zone.classList.add('is-paste-target');zone.focus();if(!navigator.clipboard||typeof navigator.clipboard.read!=='function'){waitForKeyboardPaste();return;}try{var clipboardItems=await navigator.clipboard.read(),pasted=[];for(var i=0;i<clipboardItems.length;i++){for(var j=0;j<clipboardItems[i].types.length;j++){var type=clipboardItems[i].types[j];if(type.indexOf('image/')===0){var blob=await clipboardItems[i].getType(type);pasted.push(new File([blob],'clipboard-'+Date.now()+'-'+i+'.'+(type.split('/')[1]||'png'),{type:type,lastModified:Date.now()}));break;}}}if(!pasted.length){showError('剪贴板中没有可用的图片。');return;}addFiles(pasted);zone.classList.remove('is-paste-target');}catch(e){waitForKeyboardPaste();}});document.addEventListener('paste',function(event){if(!zone.contains(document.activeElement))return;var items=(event.clipboardData||window.clipboardData).items||[],pasted=[];for(var i=0;i<items.length;i++){if(items[i].kind==='file'){var file=items[i].getAsFile();if(file&&file.type.indexOf('image/')===0)pasted.push(file);}}if(pasted.length){event.preventDefault();addFiles(pasted);zone.classList.remove('is-paste-target');}});zone.addEventListener('dragover',function(event){event.preventDefault();zone.classList.add('is-paste-target');});zone.addEventListener('dragleave',function(){zone.classList.remove('is-paste-target');});zone.addEventListener('drop',function(event){event.preventDefault();zone.classList.remove('is-paste-target');addFiles(event.dataTransfer&&event.dataTransfer.files);});})();
</script>
@endpush
